 * Escape HTML-special characters in source text so any markup it
 * contains renders inert when the result is parsed as HTML.
 */
function escapeHtml(text) {
	return text
		.replace(/&/g, '&amp;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;')
		.replace(/"/g, '&quot;')
		.replace(/'/g, '&#39;');
}

/**
 * Find case-insensitive whole-term matches of `terms` in `text`.
 * Overlapping/adjacent matches merge into a single range.
 */
export function findRanges(text, terms) {
	const ranges = [];
	for (const term of terms) {
		if (term === '') continue;
		// \b doesn't work reliably for non-word-boundary edges of
		// arbitrary terms, but for word-like terms this is the standard
		// "whole term" match. Use a lookaround-free fallback via regex escape.
		const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
		const re = new RegExp(`(^|[^\\p{L}\\p{N}_])(${escaped})(?=$|[^\\p{L}\\p{N}_])`, 'giu');
		let m;
		while ((m = re.exec(text)) !== null) {
			const start = m.index + m[1].length;
			ranges.push({ start, end: start + m[2].length });
			// avoid zero-length loops
			re.lastIndex = start + 1;
		}
	}
	// Merge overlapping or touching ranges.
	ranges.sort((a, b) => a.start - b.start || a.end - b.end);
	const merged = [];
	for (const r of ranges) {
		const last = merged[merged.length - 1];
		if (last && r.start <= last.end) {
			last.end = Math.max(last.end, r.end);
		} else {
			merged.push({ ...r });
		}
	}
	return merged;
}

/**
 * Highlight each case-insensitive whole-term occurrence of any term in
 * `text` by wrapping it in <mark data-term="...">. The text is HTML-
 * escaped first, so injected tags cannot appear as real elements.
 */
export function highlight(text, terms) {
	const escaped = escapeHtml(String(text));
	const ranges = findRanges(escaped, terms);

	let out = '';
	let pos = 0;
	for (const { start, end } of ranges) {
		out += escaped.slice(pos, start);
		const hit = escaped.slice(start, end);
		out += `<mark data-term="${hit.toLowerCase()}">${hit}</mark>`;
		pos = end;
	}
	out += escaped.slice(pos);
	return out;
}

export default highlight;
