result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/highlight/test/highlight.test.js", "content": "import { describe, it, expect } from 'vitest';
import { parse } from 'node-html-parser';
import { highlight } from '../src/index.js';

describe('highlight()', () => {
	it('wraps whole-term hits in <mark data-term>', () => {
		const html = highlight('Java and JavaScript are different.', ['java']);
		const root = parse(html);
		const marks = root.querySelectorAll('mark');
		expect(marks).toHaveLength(2);
		// "JavaScript" must NOT be highlighted (whole-term only)
		expect(marks[0].text).toBe('Java');
		expect(marks[0].getAttribute('data-term')).toBe('java');
		expect(root.text).toBe('Java and JavaScript are different.');
	});

	it('is case-insensitive', () => {
		const html = highlight('JAVA java JaVa', ['java']);
		const root = parse(html);
		const marks = root.querySelectorAll('mark');
		expect(marks).toHaveLength(3);
		marks.forEach((m) => expect(m.getAttribute('data-term')).toBe('java'));
	});

	describe('overlapping terms merge into a single mark', () => {
		const sample = 'I write javascript code in Java too.';
		const html = highlight(sample, ['java', 'javascript']);
		const root = parse(html);
		const marks = root.querySelectorAll('mark');

		it('emits exactly one mark per merged region', () => {
			expect(marks).toHaveLength(2);
		});

		it('the [java, javascript] overlap becomes one mark containing "javascript"', () => {
			const js = marks.find((m) => m.text.toLowerCase() === 'javascript');
			expect(js).toBeDefined();
			expect(js.getAttribute('data-term')).toBe('javascript');
		});

		it('standalone "Java" still gets its own mark', () => {
			const standalone = marks.filter((m) => m.text === 'Java');
			expect(standalone).toHaveLength(1);
		});

		it('full text content is preserved exactly', () => {
			expect(root.text).toBe(sample);
		});
	});

	describe('XSS safety: injected tags are inert', () => {
		const payload = '<img src=x onerror=alert(1)>';
		const html = highlight(payload, ['alert']);
		const root = parse(html);

		it('contains no img element anywhere in the parsed tree', () => {
			expect(root.querySelectorAll('img')).toHaveLength(0);
			// also check raw serialization contains no real tag
			expect(root.innerHTML).not.toContain('<img');
		});

		it('contains no onerror attribute on any node', () => {
			const all = root.querySelectorAll('*');
			for (const node of all) {
				expect(node.getAttribute('onerror')).toBeUndefined();
			}
			expect(html).not.toContain('onerror=');
		});

		it('only legit marks exist; payload text survives escaped', () => {
			const marks = root.querySelectorAll('mark');
			expect(marks).toHaveLength(1); // the word "alert"
			expect(marks[0].text).toBe('alert');
			expect(root.text).toContain('<img src=x onerror=alert(1)>');
		});

		it('script injection is also inert', () => {
			const evil = highlight('<script>alert(1)</script>', []);
			const r = parse(evil);
			expect(r.querySelectorAll('script')).toHaveLength(0);
			expect(evil).not.toContain('<script>');
		});

		it('attribute-breakout attempt stays inside a text node', () => {
			const tricky = highlight('" onmouseover="alert(1)', ['alert']);
			const r = parse(tricky);
			for (const node of r.querySelectorAll('*')) {
				expect(node.getAttribute('onmouseover')).toBeUndefined();
				expect(node.getAttribute('onmouseover="alert(1)')).toBeUndefined();
			}
		});
	});
});
"})
